# v0.8 급습 막이를 시설까지: 출진한 턴에는 거점도 시설도 칠 수 없다 (부지가 성에서 4칸까지 넓어져, 가까운 성끼리는 출진한 턴에 이웃 성의 시설 옆에 설 수 있다 — floor.js 로 확인)
import io
def rep(s, a, b, n=1):
    c = s.count(a)
    assert c == n, (c, a[:100])
    return s.replace(a, b)
p = 'src/core.js'; s = io.open(p, encoding='utf-8').read()
s = rep(s, "if (fc && pb.owner >= 0 && pb.owner !== u.f && d === 1) out.push({ kind: 'fac', b: pb, i: pf.i, c: c, r: r, d: d }); }", "if (fc && pb.owner >= 0 && pb.owner !== u.f && d === 1 && !justOut(u)) out.push({ kind: 'fac', b: pb, i: pf.i, c: c, r: r, d: d }); }")
s = rep(s, "  if (t.kind === 'base' && justOut(u)) return ERR('출진한 턴에는 거점을 칠 수 없습니다');", "  if ((t.kind === 'base' || t.kind === 'fac') && justOut(u)) return ERR('출진한 턴에는 거점과 시설을 칠 수 없습니다');")
s = rep(s, "급습을 막는 장치는 하나 — 출진한 그 턴에는 거점을 칠 수 없다. */", "급습을 막는 장치는 하나 — 출진한 그 턴에는 거점과 시설을 칠 수 없다(부대끼리는 싸울 수 있다). */")
io.open(p, 'w', encoding='utf-8').write(s)
p = 'src/ui_panels.js'; s = io.open(p, encoding='utf-8').read()
s = rep(s, "if (t.kind === 'base' && justOut(su) && hdist(su.c, su.r, c, r) <= uRange(su)) toast('출진한 턴에는 거점을 칠 수 없습니다 — 다음 턴에 공격하세요', 2800);",
           "if ((t.kind === 'base' || t.kind === 'fac') && justOut(su) && hdist(su.c, su.r, c, r) <= (t.kind === 'fac' ? 1 : uRange(su))) toast('출진한 턴에는 거점과 시설을 칠 수 없습니다 — 다음 턴에 공격하세요', 2800);")
s = rep(s, "    out.push({ kind: 'attack', label: '시설 파괴', sub: d <= 1 ? '공격' : '옆 칸에서만', ok: d <= 1, pri: true });", "    out.push({ kind: 'attack', label: '시설 파괴', sub: justOut(u) ? '출진한 턴 — 다음 턴부터' : (d <= 1 ? '공격' : '옆 칸에서만'), ok: d <= 1 && !justOut(u), pri: true });")
s = rep(s, "다만 <b>출진한 그 턴에는 거점을 칠 수 없습니다</b>(부대끼리는 싸울 수 있습니다).", "다만 <b>출진한 그 턴에는 거점과 시설을 칠 수 없습니다</b>(부대끼리는 싸울 수 있습니다).")
io.open(p, 'w', encoding='utf-8').write(s)
p = 'tests/floor.js'; s = io.open(p, encoding='utf-8').read()
s = rep(s, "    if (mode === 'attack' && !OLD && !NOBORN && t === 0) continue;             // 출진한 턴에는 거점을 칠 수 없다", "    if ((mode === 'attack' || mode === 'plot') && !OLD && !NOBORN && t === 0) continue;             // 출진한 턴에는 거점도 시설도 칠 수 없다")
s = rep(s, "      if (at === 1) T1.push([key, a.n, b.n, hd]);", "      if (at === 1 || pl === 1) T1.push([key, a.n, b.n, hd, at === 1 ? 'base' : 'facility']);")
s = rep(s, "console.log('city attacked on the deploy turn:', T1.length);", "console.log('city or facility attacked on the deploy turn:', T1.length);")
s = rep(s, "'PASS — no base can be attacked on the turn a unit is deployed'", "'PASS — no base or facility can be attacked on the turn a unit is deployed'")
io.open(p, 'w', encoding='utf-8').write(s)
p = 'tests/zonecheck.js'; s = io.open(p, encoding='utf-8').read()
s = rep(s, "  if (res && res.ok && t.kind === 'base') {", "  if (res && res.ok && t.kind === 'fac' && u._born === ROUND) VIOL.push('attacked a facility on the deploy turn: ' + uName(u) + ' round ' + ROUND);\n  if (res && res.ok && t.kind === 'base') {")
